python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-integration-service-boundary/SlackDigestBoundaryBpmn/SlackDigestBoundaryBpmn.bpmn')
root = tree.getroot()

NS = {
    'bpmn':   'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'dc':     'http://www.omg.org/spec/DD/20100524/DC',
    'di':     'http://www.omg.org/spec/DD/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}
DI_NS = 'http://www.omg.org/spec/BPMN/20100524/DI'

all_ids = {el.get('id') for el in root.iter() if el.get('id')}
errors = []

# 1 - root has BPMN namespace
assert '{http://www.omg.org/spec/BPMN/20100524/MODEL}definitions' == root.tag, f'Unexpected root: {root.tag}'

# 2 - diagram present, shapes cover all flow nodes, edges cover all seq flows
diagram = root.find('bpmndi:BPMNDiagram', NS)
assert diagram is not None, 'Missing BPMNDiagram'

proc = root.find('bpmn:process', NS)
fn_ids = {el.get('id') for el in proc
          if el.get('id')
          and not el.tag.endswith('}sequenceFlow')
          and not el.tag.endswith('}extensionElements')}
sf_ids = {el.get('id') for el in proc.findall('bpmn:sequenceFlow', NS)}

shapes = diagram.findall('.//{%s}BPMNShape' % DI_NS)
edges  = diagram.findall('.//{%s}BPMNEdge'  % DI_NS)
shape_refs = {s.get('bpmnElement') for s in shapes}
edge_refs  = {e.get('bpmnElement') for e in edges}

miss_shapes = fn_ids - shape_refs
miss_edges  = sf_ids - edge_refs
if miss_shapes: errors.append(f'Nodes missing BPMNShape: {miss_shapes}')
if miss_edges:  errors.append(f'Flows missing BPMNEdge: {miss_edges}')

# 3 - all sourceRef / targetRef resolve
for sf in proc.findall('bpmn:sequenceFlow', NS):
    for attr in ('sourceRef', 'targetRef'):
        ref = sf.get(attr)
        if ref not in all_ids:
            errors.append(f'Flow {sf.get(\"id\")} {attr}={ref} unresolved')

# 4 - no fake joins (multiple incoming on non-gateway)
gateway_tags = {'exclusiveGateway','parallelGateway','inclusiveGateway','eventBasedGateway'}
for el in proc:
    tag = el.tag.split('}')[-1]
    if tag in gateway_tags: continue
    inc = el.findall('bpmn:incoming', NS)
    if len(inc) > 1:
        errors.append(f'{el.get(\"id\")} fake join: {len(inc)} incoming flows')

# 5 - uipath:output var refs resolve
var_ids = {v.get('id') for v in root.findall('.//{http://uipath.org/schema/bpmn}inputOutput')}
for out_el in root.findall('.//{http://uipath.org/schema/bpmn}output'):
    var_ref = out_el.get('var')
    if var_ref and var_ref not in var_ids:
        errors.append(f'uipath:output var={var_ref} not declared')

if errors:
    print('ERRORS:')
    for e in errors: print(' -', e)
else:
    print('STRUCTURAL CHECK PASSED')
